import wordAudioJson from "../../../data/en/word-audio.json";
import type { WordAudioManifest } from "../../languages/types";
import { deepFreeze } from "../../shared/readonly";

/**
 * The en-us word recordings in the public assets bucket. Its own subpath, so the app loads
 * it only when a play button needs it (`loadWordAudioManifest`). The JSON is generated by
 * `bun run --cwd packages/audio-gen manifest`. Do not edit it by hand.
 */
export const EnglishWordAudio: WordAudioManifest = deepFreeze(wordAudioJson);
